ng.org/rstb/article-pdf/doi/10.1098/rstb.2023.0415/1282628/rstb.2023.0415.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1098/rstb.2023.0415", "doi": "https://doi.org/10.1098/rstb.2023.0415", "is_oa": true, "landing_page_url": "https://doi.org/10.1098/rstb.2023.0415", "pdf_url": "https://royalsocietypublishing.org/rstb/article-pdf/doi/10.1098/rstb.2023.0415/1282628/rstb.2023.0415.pdf", "source": {"id": "https://openalex.org/S91660768", "display_name": "Philosophical Transactions of the Royal Society B Biological Sciences", "issn_l": "0962-8436", "issn": ["0962-8436", "1471-2970"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "cwts-core", "dongbi-d", "jufo-2", "ki-jl-2", "medline", "norway-2", "poland-140", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319787", "host_organization_name": "Royal Society", "host_organization_lineage": ["https://openalex.org/P4310319787"], "host_organization_lineage_names": ["Royal Society"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Philosophical Transactions of the Royal Society B: Biological Sciences", "raw_type": "journal-article"}, "abstract": "Episodic memories are experienced as belonging to a self that persists in time. We review evidence concerning the nature of human episodic memory and of the sense of self and how these emerge during development, proposing that the younger child experiences a persistent self that supports a subjective experience of remembering. We then explore recent research in cognitive architectures for robotics that has investigated the possibility of forms of synthetic episodic and autobiographical memory. We show that recent advances in generative modeling can support an understanding of the emergence of self and of episodic memory, and that cognitive architectures which include a language capacity are showing progress towards the construction of a narrative self with autobiographical memory capabilities for robots. We conclude by considering the prospects for a more complete model of mental time travel in robotics and the implications of this modeling work for understanding human episodic memory and the self in time. This article is part of the theme issue 'Elements of episodic memory: lessons from 40 years of research'."}]", "excerpt_truncated": true, "source_sha256": "9a59b0885f6775598490f6996b8eb6501fa2dafec5f9ab421ac0dbcfde477a8d", "verification_required": true, "topic_domain": "memory_and_identity", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1098/rstb.2023.0415/1282628/rstb.2023.0415.pdf", "doi:10.1098/rstb.2023.0415", "openalex:W2563105546"], "source_candidates": ["https://doi.org/10.1098/rstb.2023.0415", "https://royalsocietypublishing.org/rstb/article-pdf/doi/10.1098/rstb.2023.0415/1282628/rstb.2023.0415.pdf"], "source_candidate_identities": {}}

